package com.portfolio.features.integration.github;
import com.portfolio.features.integration.github.entity.*; import com.portfolio.features.integration.github.repository.*; import com.portfolio.features.user.entity.AppUser; import java.net.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import lombok.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.client.RestClient;
@Service @RequiredArgsConstructor public class GitHubIntegrationService { private final GitHubConnectionRepository connections; private final GitHubOAuthStateRepository states; private final RestClient http=RestClient.create(); @Value("${app.github.client-id:}") String clientId; @Value("${app.github.client-secret:}") String clientSecret; @Value("${app.github.redirect-uri:}") String redirectUri; @Value("${app.github.frontend-url:http://localhost:3000}") String frontendUrl;
 @Transactional public String connect(AppUser user){if(clientId.isBlank()||redirectUri.isBlank())throw new IllegalArgumentException("GitHub integration is not configured.");String raw=UUID.randomUUID()+"-"+UUID.randomUUID();GitHubOAuthState s=new GitHubOAuthState();s.setUser(user);s.setStateHash(hash(raw));s.setExpiresAt(LocalDateTime.now().plusMinutes(10));states.save(s);return "https://github.com/login/oauth/authorize?client_id="+encode(clientId)+"&redirect_uri="+encode(redirectUri)+"&scope=read:user&state="+encode(raw);}
 @Transactional public String callback(String code,String state){try{var oauth=states.findByStateHash(hash(state)).filter(s->!s.isUsed()&&s.getExpiresAt().isAfter(LocalDateTime.now())).orElseThrow(()->new IllegalArgumentException("GitHub authorization has expired. Please try again."));oauth.setUsed(true);var token=http.post().uri("https://github.com/login/oauth/access_token").accept(MediaType.APPLICATION_JSON).body(Map.of("client_id",clientId,"client_secret",clientSecret,"code",code,"redirect_uri",redirectUri)).retrieve().body(Token.class);if(token==null||token.access_token()==null)throw new IllegalArgumentException("Unable to connect GitHub.");var user=http.get().uri("https://api.github.com/user").header("Authorization","Bearer "+token.access_token()).header("Accept","application/vnd.github+json").retrieve().body(GitHubUser.class);if(user==null)throw new IllegalArgumentException("Unable to retrieve GitHub account.");var c=connections.findByUserId(oauth.getUser().getId()).orElseGet(GitHubConnection::new);c.setUser(oauth.getUser());c.setGithubUserId(user.id());c.setGithubUsername(user.login());c.setGithubAvatarUrl(user.avatar_url());c.setAccessToken(token.access_token());c.setScope(token.scope());connections.save(c);return frontendUrl+"/dashboard/builder?github=connected";}catch(Exception e){return frontendUrl+"/dashboard/builder?github=error";}}
 @Transactional(readOnly=true) public Status status(AppUser user){return connections.findByUserId(user.getId()).map(c->new Status(true,c.getGithubUsername(),c.getGithubAvatarUrl())).orElse(new Status(false,null,null));} @Transactional public void disconnect(AppUser user){connections.findByUserId(user.getId()).ifPresent(connections::delete);} private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} private String encode(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);} public record Status(boolean connected,String username,String avatarUrl){} record Token(String access_token,String scope){} record GitHubUser(long id,String login,String avatar_url){}
}
